"""Package the direct CPU gate with process I/O and long fidelity checks."""
import json,pathlib,statistics,subprocess
P=pathlib.Path('/private/tmp')
W=P/'freetoken-4090-disk-populate'
starts=[]
for label in ('r1','r2'):
 starts.append(dict(metadata=json.loads((P/f'astra-staged-hot-reuse-cpu-auto-{label}-metadata.json').read_text()),records=[json.loads(l) for l in (P/f'astra-staged-hot-reuse-cpu-auto-{label}.jsonl').read_text().splitlines()],journal=(P/f'astra-staged-hot-reuse-cpu-auto-{label}-journal.log').read_text()))
assert all(s['metadata']['completed'] and len(s['records'])==12 for s in starts)
assert starts[-1]['metadata']['original_serving_restoration']['choices'][0]['message']['content'].strip()=='OK'
rows=[x for s in starts for x in s['records'] if not x['warmup']]
summary=[]
for kind in ('json','essay'):
 modes={mode:{key:statistics.mean(x[key] for x in rows if x['kind']==kind and x['mode']==mode) for key in ('ttft_s','decode_s','wall_s')} for mode in ('cpu','selected')}
 for mode in modes:
  modes[mode]['process_io_mean_gib']={key:statistics.mean(x['process_io']['delta'][key] for x in rows if x['kind']==kind and x['mode']==mode)/2**30 for key in ('rchar','read_bytes')}
 pairs=[]
 for s in starts:
  for repeat in range(2):
   pair={x['mode']:x for x in s['records'] if x['kind']==kind and x['repeat']==repeat and not x['warmup']}
   assert pair['cpu']['prompt']==pair['selected']['prompt']
   pairs.append(dict(start=s['metadata']['label'],repeat=repeat,cpu_wall_s=pair['cpu']['wall_s'],selected_wall_s=pair['selected']['wall_s'],wall_reduction_fraction=1-pair['selected']['wall_s']/pair['cpu']['wall_s'],text_equal=pair['cpu']['text']==pair['selected']['text'],usage_equal=pair['cpu']['usage']==pair['selected']['usage']))
 summary.append(dict(kind=kind,prompt_tokens=sorted(set(x['usage']['prompt_tokens'] for x in rows if x['kind']==kind)),completion_tokens=sorted(set(x['usage']['completion_tokens'] for x in rows if x['kind']==kind)),modes=modes,wall_reduction_fraction=1-modes['selected']['wall_s']/modes['cpu']['wall_s'],pairs=pairs))
json_rows=[x for s in starts for x in s['records'] if x['kind']=='json']
assert all(json.loads(x['text'],object_pairs_hook=list)==list(x['expected'].items()) for x in json_rows)
fidelity=[]
for s in starts:
 records=[r for r in s['metadata']['records'] if r['kind'].startswith('fidelity_')]
 assert len(records)==16
 scores={mode:sum(r['passed'] for r in records if r['mode']==mode) for mode in ('cpu','selected')}
 pairs=[]
 for name in dict.fromkeys(r['kind'] for r in records):
  pair={r['mode']:r for r in records if r['kind']==name}
  assert pair['cpu']['prompt']==pair['selected']['prompt']
  assert min(r['usage']['prompt_tokens'] for r in pair.values())>=1024
  pairs.append(dict(kind=name,expected=pair['cpu']['expected'],cpu=pair['cpu']['text'],selected=pair['selected']['text'],cpu_passed=pair['cpu']['passed'],selected_passed=pair['selected']['passed']))
 fidelity.append(dict(start=s['metadata']['label'],scores=scores,pairs=pairs))
for s in starts:
 for r in s['records']:
  a,b=r['process_io']['before'],r['process_io']['after']
  assert (a['pid'],a['starttime_ticks'])==(b['pid'],b['starttime_ticks'])
  assert all(r['process_io']['delta'][k]>=0 for k in ('rchar','read_bytes'))
result=dict(date='2026-09-05',kind='two-start balanced non-debug CPU versus staged HOT-reuse prefill under automatic adaptation, with long fidelity and external process I/O snapshots',driver=(P/'astra-staged-hot-reuse-cpu-auto-driver.py').read_text(),client=subprocess.run(['git','show','a2a09f0:bench/staged-prefill-long-output.py'],cwd=W,check=True,text=True,capture_output=True).stdout,starts=starts,summary=summary,fidelity=fidelity,post_validation=dict(json_responses=len(json_rows),all_32_values_key_order_and_multiplicity_correct=True,measured_pairs=sum(len(x['pairs']) for x in summary),all_usage_counts_match_within_pairs=all(p['usage_equal'] for x in summary for p in x['pairs']),prose_pairs_with_different_text=sum(not p['text_equal'] for x in summary if x['kind']=='essay' for p in x['pairs'])),limitations=['Four measured pairs per workload. Request-order and host page-cache effects remain possible despite reversing each prompt order across two starts.','Automatic HOT state carries between alternating modes in a start. The policy is unchanged phase aim with split histories, not the reverted decode-only experiment.','Process I/O snapshots bracket but sit outside the existing client timing interval. Server diagnostic collection and GPU step timing remain disabled.','rchar counts read syscall bytes, not native mmap memory loads. read_bytes accounts storage-layer reads for the worker and can include expert, PLE, metadata, and background I/O. These are not per-bank I/O attribution or measured device bandwidth.','Eight long fidelity prompts and exact JSON copying are limited regression checks. Prose is unscored, and CPU/GPU floating-point differences can alter text.','The only model and hardware covered here are the Qwen Flash NVFP4 checkpoint on node-4 RTX 4090, with the recorded placement and serving configuration.'])
result['analysis_script']=pathlib.Path(__file__).read_text()
(W/'bench/results/4090-staged-hot-reuse-cpu-auto-20260905.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(dict(summary=summary,fidelity=fidelity),indent=2))
